                          : "bg-white/5 text-white/45"
                      }`}
                    >
                      {collection.is_visible ? "┘ü╪╣╪º┘ä" : "┘à╪«┘ü█î"}
                    </span>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <AdminPagination
        pagination={pagination}
        disabled={loading}
        onPageChange={setPage}
      />
    </div>
  );
}

