"use client";

import { useEffect, useRef, useState } from "react";
import { HiOutlineCheckCircle, HiOutlineSearch } from "react-icons/hi";
import type { TmdbSearchResult } from "../../lib/admin-movies";

type TmdbTitleSearchProps = {
  onSelect: (tmdbId: number) => void;
  search: (
    query: string,
  ) => Promise<ApiResponse<{ results: TmdbSearchResult[] }>>;
  debounceMs?: number;
  placeholder?: string;
  label?: string;
};

type ApiResponse<T> = {
  success: boolean;
  data?: T;
  message?: string;
};

export default function TmdbTitleSearch({
  onSelect,
  search,
  debounceMs = 500,
  placeholder = "╪¼╪│╪¬╪¼┘ê ╪¿╪º ╪╣┘å┘ê╪º┘å ┘ü█î┘ä┘à █î╪º ╪│╪▒█î╪º┘äΓÇª",
  label = "╪¼╪│╪¬╪¼┘ê█î ╪╣┘å┘ê╪º┘å ╪»╪▒ TMDB",
}: TmdbTitleSearchProps) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<TmdbSearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);
  const [searched, setSearched] = useState(false);
  const [searchError, setSearchError] = useState("");
  const requestRef = useRef(0);
  const containerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const trimmed = query.trim();
    const isNumericId = /^\d+$/.test(trimmed);
    const minLength = isNumericId ? 1 : 2;

    if (trimmed.length < minLength) {
      setResults([]);
      setLoading(false);
      setOpen(false);
      setSearched(false);
      setSearchError("");
      return;
    }

    const timer = window.setTimeout(async () => {
      const requestId = ++requestRef.current;
      setLoading(true);
      setSearchError("");

      try {
        const response = await search(trimmed);

        if (requestId !== requestRef.current) {
          return;
        }

        if (response.success && response.data?.results) {
          setResults(response.data.results);
          setOpen(true);
          setSearched(true);
        } else {
          setResults([]);
          setOpen(true);
          setSearched(true);
          setSearchError(response.message || "╪¼╪│╪¬╪¼┘ê ╪º┘å╪¼╪º┘à ┘å╪┤╪».");
        }
      } catch {
        if (requestId !== requestRef.current) {
          return;
        }

        setResults([]);
        setOpen(true);
        setSearched(true);
        setSearchError("╪¼╪│╪¬╪¼┘ê ╪»╪▒ TMDB ╪º┘å╪¼╪º┘à ┘å╪┤╪».");
      } finally {
        if (requestId === requestRef.current) {
          setLoading(false);
        }
      }
    }, debounceMs);

    return () => {
      window.clearTimeout(timer);
    };
  }, [query, debounceMs, search]);

  useEffect(() => {
    const handlePointerDown = (event: MouseEvent) => {
      if (!containerRef.current?.contains(event.target as Node)) {
        setOpen(false);
      }
    };

    document.addEventListener("mousedown", handlePointerDown);

    return () => {
      document.removeEventListener("mousedown", handlePointerDown);
    };
  }, []);

  return (
    <div ref={containerRef} className="relative">
      <label className="block">
        <span className="mb-2 flex items-center gap-2 text-sm text-[#8ea4b3]">
          <HiOutlineSearch className="h-4 w-4" />
          {label}
          {loading ? (
            <span className="text-xs text-[#38bdf8]">╪»╪▒ ╪¡╪º┘ä ╪¼╪│╪¬╪¼┘êΓÇª</span>
          ) : null}
        </span>
        <input
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          onFocus={() => {
            if (results.length > 0) {
              setOpen(true);
            }
          }}
          placeholder={placeholder || "╪╣┘å┘ê╪º┘å╪î ╪│╪º┘ä █î╪º ┘å╪º┘à ╪º┘å┌»┘ä█î╪│█î ΓÇö ╪¿╪▒╪º█î ┌⌐╪» TMDB ╪º╪▓ ┘ü█î┘ä╪» ┘╛╪º█î█î┘å ╪º╪│╪¬┘ü╪º╪»┘ç ┌⌐┘å█î╪»"}
          className="w-full rounded-2xl border border-white/10 bg-[#071019] px-4 py-3 text-sm text-white placeholder:text-[#728896] outline-none transition focus:border-[#38bdf8]/45"
        />
      </label>

      {open && searched && !loading ? (
        results.length > 0 ? (
        <ul className="absolute z-30 mt-2 max-h-80 w-full overflow-y-auto rounded-2xl border border-white/10 bg-[#071019] shadow-[0_24px_60px_rgba(0,0,0,0.45)]">
          {results.map((result) => {
            const title = result.title || result.original_title || "╪¿╪»┘ê┘å ╪╣┘å┘ê╪º┘å";
            const subtitle = [
              result.original_title && result.original_title !== result.title
                ? result.original_title
                : null,
              result.release_year ? String(result.release_year) : null,
              result.tmdb_id ? `TMDB ${result.tmdb_id}` : null,
            ]
              .filter(Boolean)
              .join(" ┬╖ ");

            return (
              <li key={result.tmdb_id ?? title}>
                <button
                  type="button"
                  onClick={() => {
                    if (result.tmdb_id) {
                      onSelect(result.tmdb_id);
                      setQuery("");
                      setOpen(false);
                      setResults([]);
                    }
                  }}
                  className="flex w-full items-center gap-3 border-b border-white/5 px-4 py-3 text-right transition last:border-b-0 hover:bg-white/[0.06]"
                >
                  {result.poster_url ? (
                    <img
                      src={result.poster_url}
                      alt=""
                      className="h-16 w-11 shrink-0 rounded-lg object-cover"
                    />
                  ) : (
                    <div className="flex h-16 w-11 shrink-0 items-center justify-center rounded-lg border border-white/10 bg-white/[0.04] text-[10px] text-[#728896]">
                      TMDB
                    </div>
                  )}
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-semibold text-white">
                      {title}
                    </span>
                    {subtitle ? (
                      <span className="mt-1 block truncate text-xs text-[#8ea4b3]">
                        {subtitle}
                      </span>
                    ) : null}
                  </span>
                  <HiOutlineCheckCircle className="h-4 w-4 shrink-0 text-[#38bdf8]/70" />
                </button>
              </li>
            );
          })}
        </ul>
        ) : (
        <div className="absolute z-30 mt-2 w-full rounded-2xl border border-white/10 bg-[#071019] px-4 py-3 text-sm text-[#8ea4b3] shadow-[0_24px_60px_rgba(0,0,0,0.45)]">
          {searchError || "┘å╪¬█î╪¼┘çΓÇî╪º█î █î╪º┘ü╪¬ ┘å╪┤╪». ╪º┌»╪▒ ┌⌐╪» TMDB ╪▒╪º ┘à█îΓÇî╪»╪º┘å█î╪»╪î ╪»╪▒ ┘ü█î┘ä╪» ┬½┌⌐╪» TMDB┬╗ ┘╛╪º█î█î┘å ┘ê╪º╪▒╪» ┌⌐┘å█î╪»."}
        </div>
        )
      ) : null}
    </div>
  );
}

