                {hasSubtitle ? (
                  <span className="rounded-lg border border-[#f5c518]/30 bg-[#f5c518]/10 px-2.5 py-1.5 text-sm font-semibold text-[#f8d977] backdrop-blur">
                    ╪▓█î╪▒┘å┘ê█î╪│ ┘ü╪º╪▒╪│█î
                  </span>
