            {hoveredBucket ? (
              <p className="text-xs text-[#f8d977]">
                ╪º┘à╪¬█î╪º╪▓ {hoveredBucket.score.toLocaleString("fa-IR")}:{" "}
                {hoveredBucket.percent.toLocaleString("fa-IR")}% (
                {hoveredBucket.count.toLocaleString("fa-IR")} ╪▒╪ú█î)
              </p>
            ) : (
              <p className="text-xs text-white/35">╪▒┘ê█î ┘ç╪▒ ┘à█î┘ä┘ç ╪¿╪º█î╪│╪¬█î╪»</p>
            )}
