          >
            {buckets.map((bucket) => {
              const width = `${Math.max(bucket.percent > 0 ? 6 : 0, (bucket.percent / maxPercent) * 100)}%`;
              const isHovered = hoveredScore === bucket.score;
              const isActive = bucket.count > 0;

              return (
                <button
