"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import { HiChevronUp, HiXMark } from "react-icons/hi2";
import FilterCheckbox from "./FilterCheckbox";

export type MultiSelectOption = {
  value: string;
  label: string;
  count?: number;
  flag?: string;
  group?: string;
};

type SearchableMultiSelectProps = {
  options: MultiSelectOption[];
  value: string[];
  onChange: (values: string[]) => void;
  placeholder: string;
  searchPlaceholder?: string;
  maxHeight?: number;
  showCounts?: boolean;
  maxSelections?: number;
  columns?: 1 | 2;
};

export default function SearchableMultiSelect({
  options,
  value,
  onChange,
  placeholder,
  searchPlaceholder = "╪¼╪│╪¬╪¼┘ê...",
  maxHeight = 280,
  showCounts = true,
  maxSelections,
  columns = 1,
}: SearchableMultiSelectProps) {
  const listId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [highlight, setHighlight] = useState(0);

  const filtered = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) return options;
    return options.filter((option) => option.label.toLowerCase().includes(term));
  }, [options, query]);

  const labelByValue = useMemo(
    () => new Map(options.map((option) => [option.value, option.label])),
    [options],
  );

  const columnLists = useMemo(() => {
    if (columns === 1) {
      return [filtered];
    }
    const mid = Math.ceil(filtered.length / 2) || 1;
    return [filtered.slice(0, mid), filtered.slice(mid)];
  }, [columns, filtered]);

  useEffect(() => {
    const onPointerDown = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", onPointerDown);
    return () => document.removeEventListener("mousedown", onPointerDown);
  }, []);

  useEffect(() => {
    setHighlight(0);
  }, [query, open]);

  const toggle = (optionValue: string) => {
    if (value.includes(optionValue)) {
      onChange(value.filter((item) => item !== optionValue));
      return;
    }
    if (maxSelections && value.length >= maxSelections) {
      return;
    }
    onChange([...value, optionValue]);
  };

  const selectedLabels = value
    .map((item) => labelByValue.get(item) ?? item)
    .filter(Boolean);

  const triggerLabel =
    selectedLabels.length === 0
      ? placeholder
      : selectedLabels.length <= 2
        ? selectedLabels.join("╪î ")
        : `${selectedLabels.slice(0, 2).join("╪î ")} +${selectedLabels.length - 2}`;

  return (
    <div ref={rootRef} className="relative">
      <button
        type="button"
        aria-expanded={open}
        aria-controls={listId}
        onClick={() => setOpen((previous) => !previous)}
        className="flex w-full min-w-[140px] cursor-pointer items-center justify-between gap-3 rounded-xl border border-white/10 bg-[#1a1f2e]/95 px-4 py-3.5 text-sm text-white/90 backdrop-blur-md transition hover:border-white/20"
      >
        <span className="truncate text-right font-medium">{triggerLabel}</span>
        <HiChevronUp
          aria-hidden
          className={`h-5 w-5 shrink-0 text-white/55 transition-transform duration-200 ${
            open ? "" : "rotate-180"
          }`}
        />
      </button>

      {value.length > 0 ? (
        <div className="mt-1 flex flex-wrap gap-1">
          {value.slice(0, 3).map((item) => (
            <span
              key={item}
              className="inline-flex items-center gap-1 rounded-md border border-[#f5c518]/25 bg-[#f5c518]/10 px-2 py-0.5 text-xs text-[#f8d977]"
            >
              {labelByValue.get(item) ?? item}
              <button
                type="button"
                aria-label="╪¡╪░┘ü"
                onClick={() => toggle(item)}
                className="text-[#f5c518]/80 hover:text-[#f5c518]"
              >
                <HiXMark className="h-3 w-3" />
              </button>
            </span>
          ))}
        </div>
      ) : null}

      {open ? (
        <div
          id={listId}
          className="absolute right-0 z-40 mt-2 w-full min-w-[240px] overflow-hidden rounded-xl border border-white/10 bg-[#0d1118]/98 shadow-2xl backdrop-blur-xl"
        >
          <div className="border-b border-white/10 p-3">
            <input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder={searchPlaceholder}
              className="w-full rounded-lg border border-white/10 bg-[#0f131c] px-3 py-2.5 text-right text-sm text-white outline-none placeholder:text-white/35 focus:border-[#f5c518]/70"
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  setOpen(false);
                  return;
                }
                if (event.key === "ArrowDown") {
                  event.preventDefault();
                  setHighlight((index) => Math.min(index + 1, filtered.length - 1));
                }
                if (event.key === "ArrowUp") {
                  event.preventDefault();
                  setHighlight((index) => Math.max(index - 1, 0));
                }
                if (event.key === "Enter" && filtered[highlight]) {
                  event.preventDefault();
                  toggle(filtered[highlight].value);
                }
              }}
            />
            <div className="mt-2 flex items-center justify-between text-xs">
              <button
                type="button"
                className="text-[#f5c518] hover:underline"
                onClick={() => onChange(options.map((option) => option.value))}
              >
                ╪º┘å╪¬╪«╪º╪¿ ┘ç┘à┘ç
              </button>
              <button
                type="button"
                className="text-white/55 hover:underline"
                onClick={() => onChange([])}
              >
                ┘ç┘à┘ç ╪▒╪º ┘╛╪º┌⌐ ┌⌐┘å
              </button>
            </div>
          </div>
          <div
            className={`grid gap-1 overflow-auto p-2 ${columns === 2 ? "grid-cols-2" : "grid-cols-1"}`}
            style={{ maxHeight }}
          >
            {columnLists.map((column, columnIndex) => (
              <ul key={columnIndex} role="listbox" className="space-y-0.5">
                {column.length === 0 && columnIndex === 0 ? (
                  <li className="px-3 py-4 text-center text-xs text-white/50">
                    ┘à┘ê╪▒╪»█î █î╪º┘ü╪¬ ┘å╪┤╪»
                  </li>
                ) : null}
                {column.map((option, index) => {
                  const globalIndex =
                    columns === 2 && columnIndex === 1
                      ? columnLists[0].length + index
                      : index;
                  return (
                    <li key={option.value}>
                      <FilterCheckbox
                        checked={value.includes(option.value)}
                        onChange={() => toggle(option.value)}
                        className={highlight === globalIndex ? "bg-white/[0.04]" : ""}
                        label={
                          <span className="flex flex-wrap items-center justify-end gap-2">
                            {option.flag ? <span>{option.flag}</span> : null}
                            <span>{option.label}</span>
                            {showCounts && option.count != null ? (
                              <span className="text-xs text-white/40">({option.count})</span>
                            ) : null}
                          </span>
                        }
                      />
                    </li>
                  );
                })}
              </ul>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import React, {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  useMemo,
} from "react";
import { useRouter } from "next/navigation";
import {
  authService,
  isStaffAccount,
  isViewerAccount,
  tokenStorage,
  User,
} from "../lib/auth";
import {
  clearStaffAccessCookie,
  setStaffAccessCookie,
} from "../lib/staff-access";
import { mapAuthErrorMessage } from "../lib/auth-errors";
import { migrateAnonymousWatchProgress } from "../lib/watchProgressMigration";
import {
  fetchCurrentSession,
  invalidateSession,
  peekCachedSessionUser,
  primeSessionUser,
} from "../lib/session-service";

interface AuthContextType {
  user: User | null;
  /** True only while verifying a stored token with no cached user snapshot. */
  loading: boolean;
  /** False until client has read localStorage ΓÇö keeps SSR/hydration markup stable. */
  authReady: boolean;
  /** Token presence after client hydration. */
  hasToken: boolean;
  isAuthenticated: boolean;
  isViewer: boolean;
  isStaff: boolean;
  isRefreshing: boolean;
  login: (
    email: string,
    password: string,
    captchaToken?: string,
  ) => Promise<{ success: boolean; message?: string }>;
  staffLogin: (
    email: string,
    password: string,
    captchaToken?: string,
  ) => Promise<{ success: boolean; message?: string }>;
  register: (
    name: string,
    email: string,
    password: string,
    passwordConfirmation: string,
    captchaToken?: string,
  ) => Promise<{ success: boolean; message?: string }>;
  logout: () => Promise<void>;
  hasRole: (role: string) => boolean;
  hasPermission: (permission: string) => boolean;
  refreshUser: (options?: { includePermissions?: boolean }) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const defaultAuthContext: AuthContextType = {
  user: null,
  loading: false,
  authReady: false,
  hasToken: false,
  isAuthenticated: false,
  isViewer: false,
  isStaff: false,
  isRefreshing: false,
  login: async (
    _email?: string,
    _password?: string,
    _captchaToken?: string,
  ) => ({ success: false, message: "Auth unavailable" }),
  staffLogin: async (
    _email?: string,
    _password?: string,
    _captchaToken?: string,
  ) => ({ success: false, message: "Auth unavailable" }),
  register: async (
    _name?: string,
    _email?: string,
    _password?: string,
    _passwordConfirmation?: string,
    _captchaToken?: string,
  ) => ({ success: false, message: "Auth unavailable" }),
  logout: async () => {},
  hasRole: () => false,
  hasPermission: () => false,
  refreshUser: async () => {},
};

function readHasToken(): boolean {
  return Boolean(tokenStorage.getToken());
}

function maybeMigrateWatchProgress(user: User) {
  if (isViewerAccount(user)) {
    void migrateAnonymousWatchProgress(String(user.id));
  }
}

function syncStaffAccessCookie(user: User | null): void {
  if (user && isStaffAccount(user)) {
    setStaffAccessCookie();
    return;
  }

  clearStaffAccessCookie();
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const [hasToken, setHasToken] = useState(false);
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(false);
  const [authReady, setAuthReady] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const refreshUser = useCallback(
    async (options?: { includePermissions?: boolean }) => {
      const token = tokenStorage.getToken();
      setHasToken(Boolean(token));
      if (!token) {
        setUser(null);
        setLoading(false);
        setIsRefreshing(false);
        return;
      }

      const hadUser = Boolean(peekCachedSessionUser());
      if (!hadUser) {
        setLoading(true);
      } else {
        setIsRefreshing(true);
      }

      try {
        const result = await fetchCurrentSession({
          force: true,
          includePermissions: options?.includePermissions,
        });

        if (result.user) {
          setUser(result.user);
          syncStaffAccessCookie(result.user);
          maybeMigrateWatchProgress(result.user);
        } else if (result.status === 401 || result.status === 403) {
          setUser(null);
          setHasToken(false);
          clearStaffAccessCookie();
        }
      } catch {
        // Keep cached user on transient network errors.
      } finally {
        setLoading(false);
        setIsRefreshing(false);
      }
    },
    [],
  );

  useEffect(() => {
    const onStorage = (event: StorageEvent) => {
      if (event.key === null || event.key === "auth_token") {
        setHasToken(readHasToken());
      }
    };

    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, []);

  useEffect(() => {
    let cancelled = false;

    const bootstrap = async () => {
      const token = tokenStorage.getToken();
      setHasToken(Boolean(token));

      if (!token) {
        setUser(null);
        setLoading(false);
        clearStaffAccessCookie();
        setAuthReady(true);
        return;
      }

      const cached = peekCachedSessionUser();
      if (cached) {
        setUser(cached);
        syncStaffAccessCookie(cached);
        setLoading(false);
      } else {
        setLoading(true);
      }

      setAuthReady(true);

      const path = window.location.pathname;
      const needsPermissions =
        path === "/admin" ||
        path.startsWith("/admin/") ||
        path.startsWith("/adminbod");
      const result = await fetchCurrentSession({
        includePermissions: needsPermissions,
      });

      if (cancelled) {
        return;
      }

      if (result.user) {
        setUser(result.user);
        syncStaffAccessCookie(result.user);
        maybeMigrateWatchProgress(result.user);
      } else if (result.status === 401 || result.status === 403) {
        setUser(null);
        setHasToken(false);
        clearStaffAccessCookie();
      }

      setLoading(false);
    };

    void bootstrap();

    return () => {
      cancelled = true;
    };
  }, []);

  const login = async (email: string, password: string, captchaToken?: string) => {
    try {
      const response = await authService.login({
        email,
        password,
        captcha_token: captchaToken,
      });
      if (response.success && response.data) {
        tokenStorage.setToken(response.data.token);
        setHasToken(true);
        primeSessionUser(response.data.user);
        setUser(response.data.user);
        syncStaffAccessCookie(response.data.user);
        setLoading(false);
        maybeMigrateWatchProgress(response.data.user);
        return { success: true };
      }

      return {
        success: false,
        message: mapAuthErrorMessage(response.message),
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : "Login failed",
      };
    }
  };

  const staffLogin = async (
    email: string,
    password: string,
    captchaToken?: string,
  ) => {
    try {
      const response = await authService.staffLogin({
        email,
        password,
        captcha_token: captchaToken,
      });
      if (response.success && response.data) {
        tokenStorage.setToken(response.data.token);
        setHasToken(true);
        primeSessionUser(response.data.user);
        setUser(response.data.user);
        syncStaffAccessCookie(response.data.user);
        setLoading(false);
        return { success: true };
      }

      return {
        success: false,
        message: mapAuthErrorMessage(response.message),
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : "Login failed",
      };
    }
  };

  const register = async (
    name: string,
    email: string,
    password: string,
    passwordConfirmation: string,
    captchaToken?: string,
  ) => {
    try {
      const response = await authService.register({
        name,
        email,
        password,
        password_confirmation: passwordConfirmation,
        captcha_token: captchaToken,
      });
      if (response.success && response.data) {
        tokenStorage.setToken(response.data.token);
        setHasToken(true);
        primeSessionUser(response.data.user);
        setUser(response.data.user);
        syncStaffAccessCookie(response.data.user);
        setLoading(false);
        maybeMigrateWatchProgress(response.data.user);
        return { success: true };
      }

      return {
        success: false,
        message: response.message || "Registration failed",
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : "Registration failed",
      };
    }
  };

  const logout = async () => {
    const wasStaff = isStaffAccount(user);
    const onAdminPath =
      typeof window !== "undefined" &&
      (window.location.pathname === "/admin" ||
        window.location.pathname.startsWith("/admin/"));
    const destination =
      wasStaff && onAdminPath ? "/adminbod" : wasStaff ? "/" : "/login";

    try {
      await authService.logout();
    } catch (error) {
      console.error("Logout error:", error);
    } finally {
      invalidateSession();
      clearStaffAccessCookie();
      setHasToken(false);
      setUser(null);
      setLoading(false);

      if (onAdminPath && wasStaff) {
        window.location.replace(destination);
        return;
      }

      router.replace(destination);
    }
  };

  const hasRole = useCallback(
    (role: string): boolean => {
      if (!user) {
        return false;
      }
      return user.roles.some((r) => r.slug === role);
    },
    [user],
  );

  const hasPermission = useCallback(
    (permission: string): boolean => {
      if (!user) {
        return false;
      }

      if (user.permissions && user.permissions.length > 0) {
        return user.permissions.some((item) => item.slug === permission);
      }

      return user.roles.some((role) =>
        role.permissions?.some((item) => item.slug === permission),
      );
    },
    [user],
  );

  const isViewer = isViewerAccount(user);
  const isStaff = isStaffAccount(user);

  const value: AuthContextType = useMemo(
    () => ({
      user,
      loading,
      authReady,
      hasToken,
      isAuthenticated: Boolean(user),
      isViewer,
      isStaff,
      isRefreshing,
      login,
      staffLogin,
      register,
      logout,
      hasRole,
      hasPermission,
      refreshUser,
    }),
    [
      user,
      loading,
      authReady,
      hasToken,
      isViewer,
      isStaff,
      isRefreshing,
      hasRole,
      hasPermission,
      refreshUser,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

/** Safe for public pages when auth context is unavailable in a split bundle. */
export function useOptionalAuth(): AuthContextType {
  return useContext(AuthContext) ?? defaultAuthContext;
}

