"use client";

import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { HiOutlineMenuAlt2 } from "react-icons/hi";
import { EpisodeStillImage } from "../../../components/images";
import { useIsTvCompat } from "../../../hooks/useTvCapabilities";
import { useSeriesEpisodes } from "../../../lib/useSeriesEpisodes";
import {
  focusFirstInRoot,
  isBackKey,
  TV_FOCUS_RING_CLASS,
} from "../../../lib/tv/focus";
import type { PublicSeriesSeason } from "../../../lib/series";
import type { EpisodeSummary, SeasonSummary } from "../types/player.types";

type EpisodePanelNav = {
  seriesSlug: string;
  seriesTitle: string;
  currentSeason: number;
  currentEpisode: number;
};

type EpisodePanelProps = {
  nav: EpisodePanelNav;
  onSelect: (season: number, episode: number) => void;
  onOpenChange?: (open: boolean) => void;
  controlsVisible: boolean;
};

function mapRestSeasons(seasons: PublicSeriesSeason[]): SeasonSummary[] {
  return seasons.map((season) => ({
    seasonNumber: season.season_number,
    name: season.name,
    episodes: season.episodes.map(
      (ep): EpisodeSummary => ({
        id: String(ep.id),
        seasonNumber: season.season_number,
        episodeNumber: ep.episode_number,
        title: ep.title,
        hlsUrl: ep.hls_url,
        progressiveUrl: ep.video_url,
        subtitleUrl: ep.subtitle_url,
        dubbedAudioUrl: ep.dubbed_audio_url,
        durationSeconds: ep.duration_minutes ? ep.duration_minutes * 60 : null,
        stillUrl: ep.still_url,
        stillImage: ep.still_image ?? null,
        synopsis: ep.synopsis,
      }),
    ),
  }));
}

function formatEpisodeDuration(seconds: number | null | undefined): string {
  if (!seconds || seconds <= 0) {
    return "";
  }

  const minutes = Math.max(1, Math.round(seconds / 60));
  return `${minutes.toLocaleString("fa-IR")} ╪»┘é█î┘é┘ç`;
}

function formatSeasonLabel(seasonNumber: number, name?: string | null): string {
  if (name?.trim()) {
    return name.trim();
  }

  return `┘ü╪╡┘ä ${seasonNumber.toLocaleString("fa-IR")}`;
}

/** Corner episode picker ΓÇö loads season/episode list only after first open. */
function EpisodePanelComponent({
  nav,
  onSelect,
  onOpenChange,
  controlsVisible,
}: EpisodePanelProps) {
  const isTvCompat = useIsTvCompat();
  const panelRef = useRef<HTMLDivElement>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [loadRequested, setLoadRequested] = useState(false);
  const [selectedSeason, setSelectedSeason] = useState(nav.currentSeason);

  const { data, error, isLoading, mutate } = useSeriesEpisodes(
    nav.seriesSlug,
    loadRequested,
  );

  const seasons = useMemo(() => mapRestSeasons(data ?? []), [data]);

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    setSelectedSeason(nav.currentSeason);
  }, [isOpen, nav.currentSeason]);

  const setOpen = useCallback(
    (next: boolean) => {
      setIsOpen(next);
      onOpenChange?.(next);
    },
    [onOpenChange],
  );

  useEffect(() => {
    if (!controlsVisible && isOpen) {
      setOpen(false);
    }
  }, [controlsVisible, isOpen, setOpen]);

  useEffect(() => {
    if (!isOpen || !isTvCompat) {
      return;
    }

    const handler = (event: KeyboardEvent) => {
      if (isBackKey(event)) {
        event.preventDefault();
        event.stopPropagation();
        setOpen(false);
        return;
      }
    };

    window.addEventListener("keydown", handler, true);
    return () => window.removeEventListener("keydown", handler, true);
  }, [isOpen, isTvCompat, setOpen]);

  const visibleEpisodes = useMemo(() => {
    return seasons.find((season) => season.seasonNumber === selectedSeason)?.episodes ?? [];
  }, [seasons, selectedSeason]);

  useEffect(() => {
    if (!isOpen || !isTvCompat || !panelRef.current) {
      return;
    }

    requestAnimationFrame(() => {
      if (panelRef.current) {
        focusFirstInRoot(panelRef.current);
      }
    });
  }, [isOpen, isTvCompat, visibleEpisodes.length, selectedSeason, isLoading]);

  const handleToggle = useCallback(() => {
    if (!isOpen) {
      if (loadRequested) {
        void mutate();
      }
      setLoadRequested(true);
      setOpen(true);
      return;
    }

    setOpen(false);
  }, [isOpen, loadRequested, mutate, setOpen]);

  const handleBackdropClick = useCallback(() => {
    setOpen(false);
  }, [setOpen]);

  const handleSelect = useCallback(
    (season: number, episode: number, playable: boolean) => {
      if (!playable) {
        return;
      }

      onSelect(season, episode);
      setOpen(false);
    },
    [onSelect, setOpen],
  );

  const showTrigger = controlsVisible;

  return (
    <>
      {isOpen ? (
        <button
          type="button"
          aria-label="╪¿╪│╪¬┘å ┘ä█î╪│╪¬ ┘é╪│┘à╪¬ΓÇî┘ç╪º"
          className="absolute inset-0 z-[35] border-0 bg-transparent p-0"
          onClick={handleBackdropClick}
        />
      ) : null}

      <div
        className={`absolute top-4 right-4 z-40 ${showTrigger ? "pointer-events-auto" : "pointer-events-none"}`}
        dir="rtl"
      >
        <button
          type="button"
          data-tv-focusable={isTvCompat ? true : undefined}
          onClick={handleToggle}
          aria-label={isOpen ? "╪¿╪│╪¬┘å ┘ä█î╪│╪¬ ┘é╪│┘à╪¬ΓÇî┘ç╪º" : "┘ä█î╪│╪¬ ┘é╪│┘à╪¬ΓÇî┘ç╪º"}
          aria-expanded={isOpen}
          className={`inline-flex h-11 w-11 items-center justify-center rounded-lg text-white transition ${
            isTvCompat ? TV_FOCUS_RING_CLASS : ""
          } ${isOpen ? "bg-white/15" : "bg-black/35 hover:bg-black/50"}`}
        >
          <HiOutlineMenuAlt2 className="h-6 w-6" />
        </button>

        {isOpen ? (
          <div
            ref={panelRef}
            role={isTvCompat ? "dialog" : undefined}
            aria-label={isTvCompat ? "┘ä█î╪│╪¬ ┘é╪│┘à╪¬ΓÇî┘ç╪º" : undefined}
            data-tv-focus-group="episode-panel"
            data-episode-panel
            className="absolute top-full right-0 mt-2 flex w-[min(92vw,22rem)] flex-col overflow-hidden rounded-xl border border-white/10 bg-[#0b0f14]/95 shadow-2xl backdrop-blur-md sm:w-[24rem]"
            onClick={(event) => event.stopPropagation()}
          >
            <div className="border-b border-white/10 px-4 py-3">
              <h3 className="truncate text-right text-base font-bold text-white">
                {nav.seriesTitle}
              </h3>
            </div>

            {isLoading ? (
              <div className="flex items-center justify-center px-4 py-10">
                <div className="h-7 w-7 animate-spin rounded-full border-2 border-white/20 border-t-white" />
              </div>
            ) : error ? (
              <p className="px-4 py-6 text-center text-sm text-[#fecdd3]">
                {error instanceof Error ? error.message : "╪«╪╖╪º ╪»╪▒ ╪¿╪º╪▒┌»╪░╪º╪▒█î ┘é╪│┘à╪¬ΓÇî┘ç╪º"}
              </p>
            ) : seasons.length === 0 ? (
              <p className="px-4 py-6 text-center text-sm text-white/60">
                ┘é╪│┘à╪¬█î ╪¿╪▒╪º█î ┘å┘à╪º█î╪┤ ┘ê╪¼┘ê╪» ┘å╪»╪º╪▒╪».
              </p>
            ) : (
              <>
                <div
                  className="flex gap-2 overflow-x-auto border-b border-white/10 px-4 py-3"
                  style={{ touchAction: "pan-x" }}
                >
                  {seasons.map((season) => {
                    const active = season.seasonNumber === selectedSeason;

                    return (
                      <button
                        key={season.seasonNumber}
                        type="button"
                        data-tv-focusable={isTvCompat ? true : undefined}
                        onClick={() => setSelectedSeason(season.seasonNumber)}
                        className={`shrink-0 rounded-lg px-4 py-2 text-sm font-medium transition ${
                          isTvCompat ? TV_FOCUS_RING_CLASS : ""
                        } ${
                          active
                            ? "border border-white bg-white/10 text-white"
                            : "border border-transparent bg-black/30 text-white/70 hover:bg-white/5"
                        }`}
                      >
                        {formatSeasonLabel(season.seasonNumber, season.name)}
                      </button>
                    );
                  })}
                </div>

                <div
                  className="max-h-[min(60vh,28rem)] overflow-y-auto overscroll-contain"
                  style={{ touchAction: "pan-y" }}
                >
                  {visibleEpisodes.map((ep) => {
                    const isCurrent =
                      ep.seasonNumber === nav.currentSeason &&
                      ep.episodeNumber === nav.currentEpisode;
                    const playable = Boolean(ep.hlsUrl || ep.progressiveUrl);
                    const durationLabel = formatEpisodeDuration(ep.durationSeconds);

                    return (
                      <button
                        key={`${ep.seasonNumber}-${ep.episodeNumber}`}
                        type="button"
                        data-tv-focusable={isTvCompat ? true : undefined}
                        data-tv-grid-item={isTvCompat ? true : undefined}
                        disabled={!playable}
                        onClick={() =>
                          handleSelect(ep.seasonNumber, ep.episodeNumber, playable)
                        }
                        className={`flex w-full items-center gap-3 px-4 py-3 text-right transition ${
                          isTvCompat ? TV_FOCUS_RING_CLASS : ""
                        } ${
                          isCurrent
                            ? "bg-white/10"
                            : playable
                              ? "hover:bg-white/5"
                              : "cursor-not-allowed opacity-50"
                        }`}
                      >
                        <div className="min-w-0 flex-1">
                          <p className="text-sm text-white/70">
                            ┘é╪│┘à╪¬ {ep.episodeNumber.toLocaleString("fa-IR")}
                          </p>
                          <p className="truncate text-base font-bold text-white">
                            {ep.title || `┘é╪│┘à╪¬ ${ep.episodeNumber}`}
                          </p>
                          {durationLabel ? (
                            <p className="text-sm text-white/60">{durationLabel}</p>
                          ) : !playable ? (
                            <p className="text-sm text-white/50">╪¿┘ç ╪▓┘ê╪»█î</p>
                          ) : null}
                        </div>

                        <div className="relative h-16 w-28 shrink-0 overflow-hidden rounded-md bg-white/10">
                          {ep.stillUrl || ep.stillImage ? (
                            <EpisodeStillImage
                              seriesTitle={nav.seriesTitle}
                              seasonNumber={ep.seasonNumber}
                              episodeNumber={ep.episodeNumber}
                              image={ep.stillImage}
                              src={ep.stillUrl}
                              usage="episode-card"
                              sizes="112px"
                              loading="lazy"
                            />
                          ) : null}
                        </div>
                      </button>
                    );
                  })}
                </div>
              </>
            )}
          </div>
        ) : null}
      </div>
    </>
  );
}

export const EpisodePanel = memo(EpisodePanelComponent);

type PlayerMenuRadioOptionProps = {
  label: string;
  selected: boolean;
  onSelect: () => void;
  detail?: string;
};

/** Radio-style row for player dropdown menus (RTL). */
export function PlayerMenuRadioOption({
  label,
  selected,
  onSelect,
  detail,
}: PlayerMenuRadioOptionProps) {
  return (
    <button
      type="button"
      data-player-menu-item
      tabIndex={0}
      role="option"
      aria-selected={selected}
      onClick={onSelect}
      className={`flex w-full items-center justify-between gap-3 rounded-xl px-3 py-2.5 text-right transition ${
        selected ? "text-white" : "text-[#d6e3ea] hover:bg-white/[0.05]"
      }`}
    >
      <span className="flex min-w-0 flex-1 flex-col">
        <span className="text-sm font-medium">{label}</span>
        {/* {detail ? (
          <span className="mt-0.5 text-xs text-[#8ea4b3]">{detail}</span>
        ) : null} */}
      </span>
      <span
        className={`inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 ${
          selected ? "border-[#38bdf8]" : "border-white/35"
        }`}
        aria-hidden
      >
        {selected ? <span className="h-2.5 w-2.5 rounded-full bg-[#38bdf8]" /> : null}
      </span>
    </button>
  );
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  HiOutlineArrowLeft,
  HiOutlineArrowRight,
  HiOutlineFastForward,
  HiOutlineMenuAlt3,
  HiOutlineRewind,
} from "react-icons/hi";
import { IoPlaySharp } from "react-icons/io5";
import { ControlBar } from "./ControlBar";
import { EpisodePanel } from "./EpisodePanel";
import { ErrorOverlay } from "./ErrorOverlay";
import { LoadingOverlay } from "./LoadingOverlay";
import { NextEpisodeCountdown } from "./NextEpisodeCountdown";
import { SkipIntroButton, SkipRecapButton } from "./SkipButtons";
import { SubtitleLayer, type SubtitleLayerHandle } from "./SubtitleLayer";
import { useAuth } from "../../../contexts/AuthContext";
import { usePlayer } from "../hooks/usePlayer";
import { usePlayerGestures } from "../hooks/usePlayerGestures";
import { usePlayerKeyboard } from "../hooks/usePlayerKeyboard";
import { useMediaSession } from "../hooks/useMediaSession";
import { useTvFocusNavigation } from "../hooks/useTvFocusNavigation";
import { usePlayerBootPhase } from "../hooks/usePlayerBootPhase";
import { getEngineLabel } from "../services/capability";
import { useWatchProgress } from "../hooks/useWatchProgress";
import { useRecordContentView } from "../hooks/useRecordContentView";
import { createDefaultTrackerConfig, ProgressTracker } from "../services/ProgressTracker";
import { PROGRESS_CONSTANTS } from "../services/progress.types";
import { selectIsLoading, usePlayerStore } from "../store/playerStore";
import type { PlayerShellProps } from "../types/player.types";
import { buildPlaybackSubtitleUrl } from "../utils/format";
import { isSameOriginMediaRequest } from "../../../lib/playback-networking";
import { optimizeManagedImageUrl } from "../../../lib/cinema-image";
import { tokenStorage } from "../../../lib/token-storage";

/**
 * Production-grade player shell ΓÇö composes controller, controls, and overlays.
 */
function PlayerShellComponent({
  media,
  watchMedia,
  backHref,
  immersive = false,
  isSourceTransitioning = false,
  seriesContext,
  onEpisodeSelect,
  onEnded,
}: PlayerShellProps) {
  const router = useRouter();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const controlsRef = useRef<HTMLDivElement | null>(null);
  const tvGateButtonRef = useRef<HTMLButtonElement | null>(null);
  const subtitleLayerRef = useRef<SubtitleLayerHandle | null>(null);
  const managedSubtitleUrl = useMemo(
    () => buildPlaybackSubtitleUrl(media.subtitleUrl),
    [media.subtitleUrl],
  );

  const { user, isAuthenticated, isViewer } = useAuth();

  const resumeDecision = useMemo(() => {
    if (!watchMedia) {
      return {
        resumeTime: null as number | null,
      };
    }

    const decision = ProgressTracker.peekResumeDecision(
      watchMedia,
      user?.id != null ? String(user.id) : null,
    );

    const resumeTime =
      decision.resumeTime >= PROGRESS_CONSTANTS.RESUME_MIN_SECONDS
        ? decision.resumeTime
        : null;

    return {
      resumeTime,
    };
  }, [watchMedia, user]);

  const [isDraggingSeek, setIsDraggingSeek] = useState(false);
  const [seekFeedback, setSeekFeedback] = useState<{
    side: "left" | "right";
    amount: number;
    key: number;
  } | null>(null);
  const seekFeedbackKeyRef = useRef(0);

  const {
    videoRef,
    pause,
    togglePlay,
    seekBy,
    seekTo,
    setVolume,
    toggleMute,
    setPlaybackRate,
    selectQuality,
    selectAudio,
    selectSubtitle,
    setSubtitleDelay,
    setSubtitleStyle,
    recover,
    revealControls,
    toggleControls,
    cancelAutoplay,
    skipIntro,
    skipRecap,
  } = usePlayer({
    media,
    seriesContext,
    onEpisodeSelect,
    onEnded,
    initialResumeTime: resumeDecision.resumeTime,
    startupMode: "auto",
    pendingResumeTime: resumeDecision.resumeTime,
    subtitleLayerRef,
  });
  const fsmState = usePlayerStore((s) => s.fsmState);
  const currentTime = usePlayerStore((s) => s.currentTime);
  const duration = usePlayerStore((s) => s.duration);
  const readyState = usePlayerStore((s) => s.readyState);
  const isLoading = usePlayerStore(selectIsLoading);
  const error = usePlayerStore((s) => s.error);
  const showControls = usePlayerStore((s) => s.showControls);
  const isPlaying = usePlayerStore((s) => s.isPlaying);
  const setIsFullscreen = usePlayerStore((s) => s.setIsFullscreen);
  const usingHlsJs = usePlayerStore((s) => s.usingHlsJs);
  const engineId = usePlayerStore((s) => s.engineId);
  const isTv = usePlayerStore((s) => s.isTv);
  const tvPlayBlocked = usePlayerStore((s) => s.tvPlayBlocked);
  const setTvPlayBlocked = usePlayerStore((s) => s.setTvPlayBlocked);
  const openMenu = usePlayerStore((s) => s.openMenu);
  const selectedSubtitle = usePlayerStore((s) => s.selectedSubtitle);
  const subtitleFontSize = usePlayerStore((s) => s.subtitleFontSize);
  const subtitleFontColor = usePlayerStore((s) => s.subtitleFontColor);
  const subtitleBackground = usePlayerStore((s) => s.subtitleBackground);
  const [episodePanelOpen, setEpisodePanelOpen] = useState(false);
  const autoplayCountdown = usePlayerStore((s) => s.autoplayCountdown);
  const showSkipIntro = usePlayerStore((s) => s.showSkipIntro);
  const showSkipRecap = usePlayerStore((s) => s.showSkipRecap);
  const volume = usePlayerStore((s) => s.volume);
  const subtitleOptions = usePlayerStore((s) => s.subtitleOptions);
  const selectedSubtitleStore = usePlayerStore((s) => s.selectedSubtitle);
  const setSelectedSubtitle = usePlayerStore((s) => s.setSelectedSubtitle);
  const abrPhase = usePlayerStore((s) => s.abrPhase);
  const autoQualityLabel = usePlayerStore((s) => s.autoQualityLabel);

  const isReady = readyState >= HTMLMediaElement.HAVE_FUTURE_DATA;
  const { controlsEnabled, progressEnabled } = usePlayerBootPhase(
    isReady,
    isPlaying,
    videoRef,
  );

  useWatchProgress({
    media: watchMedia ?? null,
    userId: user?.id != null ? String(user.id) : null,
    isAuthenticated: isAuthenticated && isViewer,
    enabled: progressEnabled,
    currentTime,
    duration,
    isPlaying,
    onServerResumeSeek: seekTo,
  });

  useRecordContentView({
    media: watchMedia ?? null,
    currentTime,
    isPlaying,
    enabled: progressEnabled,
  });

  const canUsePiP = useMemo(
    () =>
      typeof document !== "undefined" &&
      Boolean(document.pictureInPictureEnabled),
    [],
  );

  const videoCrossOrigin = useMemo((): "anonymous" | undefined => {
    if (typeof window === "undefined") {
      return undefined;
    }

    const playbackUrl =
      media.src?.trim() || media.progressiveUrl?.trim() || media.dashUrl?.trim() || "";

    return playbackUrl && isSameOriginMediaRequest(playbackUrl)
      ? "anonymous"
      : undefined;
  }, [media.src, media.progressiveUrl, media.dashUrl]);

  const toggleFullscreen = useCallback(async () => {
    if (!containerRef.current) {
      return;
    }

    try {
      if (!document.fullscreenElement) {
        await containerRef.current.requestFullscreen();
      } else {
        await document.exitFullscreen();
      }
    } catch {
      usePlayerStore.getState().applySnapshot({
        error: "╪¬╪║█î█î╪▒ ╪¡╪º┘ä╪¬ ╪¬┘à╪º┘àΓÇî╪╡┘ü╪¡┘ç ╪»╪▒ ╪º█î┘å ┘à╪▒┘ê╪▒┌»╪▒ ╪º┘å╪¼╪º┘à ┘å╪┤╪».",
      });
    }
  }, []);

  const togglePiP = useCallback(async () => {
    const video = videoRef.current;
    if (!video || !canUsePiP) {
      return;
    }

    try {
      if (document.pictureInPictureElement) {
        await document.exitPictureInPicture();
      } else {
        await video.requestPictureInPicture();
      }
    } catch {
      // PiP unavailable ΓÇö silent in production.
    }
  }, [canUsePiP, videoRef]);

  const toggleSubtitles = useCallback(() => {
    if (subtitleOptions.length === 0) {
      return;
    }

    const next =
      selectedSubtitleStore === -1
        ? subtitleOptions.find((o) => o.value >= 0)?.value ?? 0
        : -1;
    selectSubtitle(next);
    setSelectedSubtitle(next);
  }, [selectSubtitle, selectedSubtitleStore, setSelectedSubtitle, subtitleOptions]);

  const goNextEpisode = useCallback(() => {
    const next = seriesContext?.nextEpisode;
    if (next && onEpisodeSelect) {
      onEpisodeSelect(next.seasonNumber, next.episodeNumber);
    }
  }, [onEpisodeSelect, seriesContext?.nextEpisode]);

  const handleVideoAreaClick = useCallback(() => {
    toggleControls();
  }, [toggleControls]);

  const controlsInteractive =
    showControls || !isPlaying || openMenu !== null || episodePanelOpen;

  const goPrevEpisode = useCallback(() => {
    const prev = seriesContext?.prevEpisode;
    if (prev && onEpisodeSelect) {
      onEpisodeSelect(prev.seasonNumber, prev.episodeNumber);
    }
  }, [onEpisodeSelect, seriesContext?.prevEpisode]);

  const handleSeekByWithFeedback = useCallback(
    (seconds: number) => {
      seekBy(seconds);
      seekFeedbackKeyRef.current += 1;
      setSeekFeedback({
        side: seconds >= 0 ? "right" : "left",
        amount: Math.abs(seconds),
        key: seekFeedbackKeyRef.current,
      });
      window.setTimeout(() => setSeekFeedback(null), 800);
    },
    [seekBy],
  );

  const handleBack = useCallback(() => {
    if (episodePanelOpen) {
      setEpisodePanelOpen(false);
      return;
    }

    if (openMenu) {
      usePlayerStore.getState().setOpenMenu(null);
      return;
    }

    // Persist progress immediately so Continue Watching works without a home refresh.
    const video = videoRef.current;
    if (watchMedia && video && Number.isFinite(video.currentTime) && video.currentTime > 0) {
      const tracker = ProgressTracker.getInstance();
      tracker.init(
        createDefaultTrackerConfig({
          userId: user?.id != null ? String(user.id) : null,
          isAuthenticated: isAuthenticated && isViewer,
          getAuthToken: () => tokenStorage.getToken(),
        }),
      );
      tracker.attachMedia(watchMedia);
      if (Number.isFinite(video.duration) && video.duration > 0) {
        tracker.updateDuration(video.duration);
      }
      tracker.tick(video.currentTime, video.duration || undefined);
      tracker.pause();
    }

    if (backHref) {
      router.push(backHref);
    } else {
      router.back();
    }
  }, [
    backHref,
    episodePanelOpen,
    isAuthenticated,
    isViewer,
    openMenu,
    router,
    user?.id,
    videoRef,
    watchMedia,
  ]);

  usePlayerKeyboard(
    containerRef,
    {
      togglePlay,
      seekBy: handleSeekByWithFeedback,
      setVolume,
      toggleMute,
      toggleFullscreen,
      toggleSubtitles,
