  if (item.catalogKind === "series") {
    parts.push("╪│╪▒█î╪º┘ä");
  } else {
    parts.push("┘ü█î┘ä┘à");
  }

  const rating = item.rating ?? item.details.rating;
  if (rating != null && !Number.isNaN(rating)) {
    parts.push(`IMDb ${Math.round(rating * 10) / 10}`);
  }

  return parts.join(" ┬╖ ");
}

