/**
 * Recursively removes null, undefined, empty strings, and empty arrays/objects
 * to shrink admin form payloads before network submission.
 */
export function cleanPayload<T>(value: T): T {
  if (value === null || value === undefined) {
    return undefined as T;
  }

  if (typeof value === "string") {
    const trimmed = value.trim();

    return (trimmed === "" ? undefined : trimmed) as T;
  }

  if (Array.isArray(value)) {
    const cleaned = value
      .map((item) => cleanPayload(item))
      .filter((item) => item !== undefined);

    return (cleaned.length === 0 ? undefined : cleaned) as T;
  }

  if (typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>)
      .map(([key, nested]) => [key, cleanPayload(nested)] as const)
      .filter(([, nested]) => nested !== undefined);

    if (entries.length === 0) {
      return undefined as T;
    }

    return Object.fromEntries(entries) as T;
  }

  return value;
}

export function payloadByteSize(value: unknown): number {
  try {
    return new TextEncoder().encode(JSON.stringify(value)).length;
  } catch {
    return JSON.stringify(value).length;
  }
}

export function logPayloadSize(label: string, before: unknown, after: unknown): void {
  if (process.env.NODE_ENV === "production") {
    return;
  }

  const beforeBytes = payloadByteSize(before);
  const afterBytes = payloadByteSize(after);
  const reduction =
    beforeBytes > 0 ? Math.round(((beforeBytes - afterBytes) / beforeBytes) * 100) : 0;

  console.info(
    `[cleanPayload] ${label}: ${beforeBytes}B ΓåÆ ${afterBytes}B (${reduction}% reduction)`,
  );
}

const genericEpisodeTitlePattern =
  /^(?:episode|╪º┘╛█î╪▓┘ê╪»|┘é╪│┘à╪¬)\s*#?\s*[\d\u06F0-\u06F9\u0660-\u0669]+$/iu;

function normalizeEpisodeTitleInput(title: string | null | undefined) {
  return (title ?? "")
    .replace(/[\u200e\u200f\u202a-\u202e\u2066-\u2069]/gu, "")
    .trim();
}

export function isGenericEpisodeTitle(title: string | null | undefined) {
  const trimmed = normalizeEpisodeTitleInput(title);

  if (!trimmed) {
    return true;
  }

  return genericEpisodeTitlePattern.test(trimmed);
}

export function resolveEpisodeTitle(
  candidates: Array<string | null | undefined>,
  _episodeNumber?: number | string,
) {
  for (const candidate of candidates) {
    const trimmed = normalizeEpisodeTitleInput(candidate);

    if (trimmed && !isGenericEpisodeTitle(trimmed)) {
      return trimmed;
    }
  }

  return "";
}

export function formatEpisodeHeading(
  episodeNumber: number | string,
  title: string | null | undefined,
  extraCandidates: Array<string | null | undefined> = [],
) {
  const resolvedTitle = resolveEpisodeTitle([title, ...extraCandidates]);

  if (!resolvedTitle) {
    return `┘é╪│┘à╪¬ ${episodeNumber}`;
  }

  return `┘é╪│┘à╪¬ ${episodeNumber}: ${resolvedTitle}`;
}

